/* wkmidiio.c — implementation of wkmidiio.h over the wit-bindgen C bindings.
 *
 * The bindings (gen/wkmidi.h + gen/wkmidi.c + gen/wkmidi_component_type.o)
 * are regenerated by build.sh into THIS port's gen/, from the shared WIT:
 *
 *     wit-bindgen c --world wkmidi ../midi-compat/wit --out-dir gen
 *
 * so the interface has exactly one definition in the tree even though the C
 * wrapper is local. See wkmidiio.h for why the wrapper is local.
 */
#include "wkmidiio.h"

#include <string.h>

#include "wkmidi.h" /* gen/, on the include path */

static struct {
    int in_open;
    int out_open;
    wk_midi_midi_own_input_t in;
    wk_midi_midi_own_output_t out;
} G;

int wkmidi_open_in(void)
{
    if (G.in_open)
        return -1;
    G.in = wk_midi_midi_constructor_input();
    G.in_open = 1;
    return 0;
}

int wkmidi_open_out(void)
{
    if (G.out_open)
        return -1;
    G.out = wk_midi_midi_constructor_output();
    G.out_open = 1;
    return 0;
}

int wkmidi_recv(uint8_t *buf, size_t cap)
{
    if (!G.in_open || cap == 0)
        return 0;
    wkmidi_list_u8_t msg;
    if (!wk_midi_midi_method_input_receive(wk_midi_midi_borrow_input(G.in), &msg))
        return 0; /* queue empty */
    size_t n = msg.len < cap ? msg.len : cap;
    memcpy(buf, msg.ptr, n);
    /* The option's list was canonical-ABI-allocated in guest memory by the
     * lift; free it now that the bytes are copied out. */
    wkmidi_list_u8_free(&msg);
    return (int) n;
}

void wkmidi_send(const uint8_t *buf, size_t len)
{
    if (!G.out_open || len == 0)
        return;
    /* `send`'s list parameter is borrowed for the duration of the call — the
     * lowering passes ptr+len and the host copies — so a caller's stack
     * buffer is fine and nothing here has to allocate or free. The cast away
     * from const is the bindings' signature, not a write. */
    wkmidi_list_u8_t list = { (uint8_t *) buf, len };
    wk_midi_midi_method_output_send(wk_midi_midi_borrow_output(G.out), &list);
}
